/**
 * Hypothesis model for dsh-data-analyst.
 *
 * PRD §14: A hypothesis is a testable statement proposed by the agent
 * to explain the analytical goal. Hypotheses are generated by the LLM
 * (reasoning layer, PRD §10.1) and tested with deterministic analysis
 * (M3 engine). The service layer never generates hypotheses itself.
 *
 * Example (PRD §14):
 *   { "id": "H1", "statement": "Revenue decline was caused by lower
 *    sales volume.", "status": "proposed" }
 */

export type HypothesisStatus =
  | "proposed"
  | "testing"
  | "supported"
  | "rejected"
  | "inconclusive";

export type Hypothesis = {
  /** Per-investigation sequential ID: "H1", "H2", ... (PRD §14 example) */
  id: string;
  investigationId: string;
  statement: string;
  rationale?: string;
  status: HypothesisStatus;
};

export const HYPOTHESIS_STATUSES: readonly HypothesisStatus[] = [
  "proposed",
  "testing",
  "supported",
  "rejected",
  "inconclusive",
];

export function isHypothesisStatus(value: unknown): value is HypothesisStatus {
  return (
    typeof value === "string" &&
    (HYPOTHESIS_STATUSES as readonly string[]).includes(value)
  );
}
